fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Since `list` is guaranteed to be non-empty, `min()` on the iterator of lengths
    // will always return `Some(usize)`, so `unwrap()` is safe here.
    list.iter()
        .map(|inner| inner.len())
        .min()
        .unwrap()
}

